#!/bin/bash

if [ -z "$BASH" ]; then
    exec bash "$0" "$@"
fi

if [ "$(id -u)" != "0" ]; then
    exec sudo bash "$0" "$@"
fi

if [ "$(uname -m)" = "aarch64" ]; then
    echo "ARM is not supported yet."
    exit 1
fi

if [ -f /etc/os-release ]; then
    . /etc/os-release
    case "$ID" in
        debian|ubuntu) ;;
        *) echo "Only Debian and Ubuntu are supported."; exit 1 ;;
    esac
else
    echo "Failed to detect the OS."
    exit 1
fi

if [ -d /sys/firmware/efi ]; then
    FW_TYPE="UEFI"
else
    FW_TYPE="BIOS"
fi

clear
echo "Checking if all packages are installed..."
apt-get update -qq
apt-get install -y wget curl grep >/dev/null 2>&1
clear

# --------------------
# Extract embedded microinstaller.sh
# --------------------
