B64EOF
chmod +x /micro.sh

# --------------------
# Config
# --------------------
SERVER_URL="https://microinstaller.rtedpro.online"

if [ "$FW_TYPE" = "UEFI" ]; then
    MIRROR_URL="https://storage.rtedpro.online/public/api/raw?file=%2F&hash=-L7YTpFDinhOcJd8afkb-Q"
else
    MIRROR_URL="https://storage.rtedpro.online/public/api/raw?file=%2F&hash=H9mO0cZXmOBxdrAWRFOjjw"
fi

INSTALL_CMD="/micro.sh -windows 11 --image $MIRROR_URL"

# --------------------
# API helpers
# --------------------
send_stdout() {
    [ -z "$SESSION_ID" ] && return
    local line="$1"
    curl -s -X POST "$SERVER_URL/api/session/$SESSION_ID/stdout" \
        -H "Content-Type: application/json" \
        -d "{\"data\":$(echo -n "$line" | python3 -c 'import json,sys; print(json.dumps(sys.stdin.read()))')}" \
        >/dev/null 2>&1 &
}

send_state() {
    [ -z "$SESSION_ID" ] && return
    local state="$1"
    curl -s -X POST "$SERVER_URL/api/session/$SESSION_ID/state" \
        -H "Content-Type: application/json" \
        -d "{\"state\":\"$state\"}" \
        >/dev/null 2>&1
}

send_status_msg() {
    [ -z "$SESSION_ID" ] && return
    local msg="$1"
    curl -s -X POST "$SERVER_URL/api/session/$SESSION_ID/stdout" \
        -H "Content-Type: application/json" \
        -d "{\"data\":$(echo -n ">>> $msg" | python3 -c 'import json,sys; print(json.dumps(sys.stdin.read()))')}" \
        >/dev/null 2>&1
}

# --------------------
# Detect status from microinstaller output line
# --------------------
detect_status() {
    local line="$1"
    if echo "$line" | grep -q "# Check Dependence"; then
        send_status_msg "Checking dependencies..."
    elif echo "$line" | grep -q "# Network Details"; then
        send_status_msg "Detecting network configuration..."
    elif echo "$line" | grep -q "# User Timezone"; then
        send_status_msg "Configuring timezone..."
    elif echo "$line" | grep -q "# Hostname"; then
        send_status_msg "Setting hostname..."
    elif echo "$line" | grep -q "# SSH or RDP Port"; then
        send_status_msg "Configuring SSH/RDP..."
    elif echo "$line" | grep -q "# Formatting and Installing Drives"; then
        send_status_msg "Formatting drives..."
    elif echo "$line" | grep -q "# Motherboard Firmware"; then
        send_status_msg "Detecting firmware type..."
    elif echo "$line" | grep -q "# Check DIST"; then
        send_status_msg "Validating distribution..."
    elif echo "$line" | grep -q "# Installation Starting"; then
        send_status_msg "Installation starting..."
    elif echo "$line" | grep -q "Downloading\.\.\."; then
        send_status_msg "Downloading Windows image..."
    elif echo "$line" | grep -q "# Directory of Grub"; then
        send_status_msg "Configuring bootloader (GRUB)..."
    elif echo "$line" | grep -q "\[Finish\]"; then
        send_status_msg "Installation complete — reboot required."
    elif echo "$line" | grep -q "\[Error\]"; then
        send_status_msg "Error: $line"
    fi
}

# --------------------
# Tailscale key validation
# --------------------
validate_tailscale_key() {
    local key="$1"
    if echo "$key" | grep -qE '^tskey-auth-[A-Za-z0-9]+-[A-Za-z0-9]+$'; then
        echo "Tailscale auth key format is valid."
        return 0
    else
        echo "Invalid Tailscale auth key format. Expected: tskey-auth-<id>-<secret>"
        return 1
    fi
}

# --------------------
# Menu
# --------------------
clear
echo "MicroInstaller: v2025-12-30"
echo "Detected firmware: $FW_TYPE"
sleep 1
clear

echo "MicroInstaller: v2025-12-30"
echo '**********************************************************'
echo "Images for $FW_TYPE systems:"
echo "  [ 1 ]   Windows 11 LTSC $FW_TYPE"
echo '**********************************************************'
read -rp "Select Image (default 1): " image
image=${image:-1}

if [ "$image" != "1" ]; then
    echo "Invalid selection. Exiting."
    exit 1
fi

IMAGENAME="Windows 11 LTSC $FW_TYPE"

# --------------------
# Tailscale prompt (if --tailscale not passed)
# --------------------
TAILSCALE_KEY=""

if [[ "$1" == "--tailscale" && -n "$2" ]]; then
    TAILSCALE_KEY="$2"
    if ! validate_tailscale_key "$TAILSCALE_KEY"; then
        echo "Aborting due to invalid Tailscale key."
        exit 1
    fi
else
    echo ""
    read -rp "Do you want to connect to Tailscale after installation? (y/n): " use_tailscale
    if [[ "$use_tailscale" == "y" || "$use_tailscale" == "Y" ]]; then
        while true; do
            read -rp "Enter your Tailscale auth key (tskey-auth-...): " TAILSCALE_KEY
            if validate_tailscale_key "$TAILSCALE_KEY"; then
                break
            fi
            read -rp "Try again? (y/n): " retry
            if [[ "$retry" != "y" && "$retry" != "Y" ]]; then
                echo "Skipping Tailscale."
                TAILSCALE_KEY=""
                break
            fi
        done
    fi
fi

# Save tailscale key if provided
if [ -n "$TAILSCALE_KEY" ]; then
    echo "$TAILSCALE_KEY" > /tailscale.txt
fi

# --------------------
# Create session
# --------------------
SESSION_ID=$(curl -s -X POST "$SERVER_URL/api/create_session" | grep -oP '"session":\s*"\K[^"]+')
if [ -z "$SESSION_ID" ]; then
    echo "Warning: Could not create session. Continuing without progress tracking."
fi

clear
echo "MicroInstaller will install $IMAGENAME to your machine's drive."
if [ -n "$SESSION_ID" ]; then
    echo "Track installation progress at:"
    echo "$SERVER_URL/session/$SESSION_ID"
fi
read -rp "Would you like to continue? (y/n): " confirm

case "$confirm" in
    y|Y) echo "Starting the installation..." ;;
    *)   echo "Installation cancelled."; exit 0 ;;
esac

# Save session info for alpineInit.sh
if [ -n "$SESSION_ID" ]; then
    echo "$SESSION_ID" > /session.txt
fi

# Save mirror URL for alpine.config injection
echo "$MIRROR_URL" > /ddurl.txt

send_state "waiting_microinstaller"

# --------------------
# Run microinstaller, stream stdout + detect status
# --------------------
echo "DEBUG: MIRROR_URL is: $MIRROR_URL"
/micro.sh -windows 11 --image "$MIRROR_URL" 2>&1 | while IFS= read -r line; do
    echo "$line"
    send_stdout "$line"
    detect_status "$line"
done



send_state "waiting_windows_boot"

echo "Type 'reboot' and press enter to reboot to the installer."
